CREATE OR REPLACE FUNCTION platform_private.regulatory_storage_legacy_write(p_name text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE org uuid; BEGIN org:=platform_private.catalog_tenant_actor('mutate'); RETURN EXISTS(SELECT 1 FROM public.microorganism_regulatory_dossiers d JOIN public.microrganismos m ON m.id=d.microorganism_id WHERE d.id=public.fn_regulatory_storage_dossier_id(p_name) AND d.product_id IS NULL AND d.deleted_at IS NULL AND d.status IN ('DRAFT','PENDING_REVIEW') AND m.owner_organization_id=org AND NOT EXISTS(SELECT 1 FROM public.microorganism_regulatory_publication_snapshots WHERE dossier_id=d.id)); EXCEPTION WHEN insufficient_privilege THEN RETURN false; END $$;
REVOKE ALL ON FUNCTION platform_private.regulatory_storage_legacy_write(text) FROM PUBLIC,anon,service_role; GRANT EXECUTE ON FUNCTION platform_private.regulatory_storage_legacy_write(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.fn_regulatory_storage_can_read(_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT platform_private.product_regulatory_storage_read_allowed(_name) $$;
CREATE OR REPLACE FUNCTION public.fn_regulatory_storage_can_write(_name text) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT platform_private.regulatory_storage_legacy_write(_name) $$;